    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(60, 40) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    opPlane(context, id + "roof", { "plane" : plane(vector(30, 0, 30) * millimeter, vector(-0.316228, 0, 0.948683), vector(0.948683, 0, 0.316228)), "width" : 100 * millimeter, "height" : 100 * millimeter });
    const bossSketch = newSketchOnPlane(context, id + "bossSketch", { "sketchPlane" : plane(vector(0, 0, 10) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(bossSketch, "circle1", { "center" : vector(8, 8) * millimeter, "radius" : 3 * millimeter });
    skSolve(bossSketch);
    extrude(context, id + "boss", { "entities" : qSketchRegion(id + "bossSketch"), "endBound" : BoundingType.UP_TO_SURFACE, "endBoundEntityFace" : qCreatedBy(id + "roof", EntityType.FACE), "operationType" : NewBodyOperationType.ADD, "defaultScope" : false, "booleanScope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
